// === Tab: mySketch ===
let program;
let active = false, cnt = 0;

function setup() {
	pixelDensity(1);
	const canvas = createCanvas(1112, 834,WEBGL);
	rectMode(CENTER);
	noStroke();
	fill(1);
	program = createShader(vert,frag);
}

function draw() {
	if (!active && frameCount > 1) {return;}
  const ang = (cnt ++) / 180 * PI - PI / 2;
  const lightPos = [cos(ang), 0, sin(ang)];

  shader(program);
  background(0);
	program.setUniform('res',[width,height]);
	program.setUniform('lightPos', lightPos);
	program.setUniform('roughness', constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / height, 0, 1));
	program.setUniform('metallic', constrain(1.0 - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / width, 0, 1));
  rect(0,0,width,height);
}

function mouseClicked() {
	active = !active;
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

const vert=`
#ifdef GL_ES
precision highp float;
precision highp int;
#endif

#extension GL_OES_standard_derivatives : enable
attribute vec3 aPosition;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;
void main() {
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
}`;




const frag=`
#ifdef GL_ES
precision highp float;
#endif

#define PI 3.14159265358979323846
#define REFLECTION_SAMPLE_COUNT 64
#define BRDF_SAMPLE_COUNT 64

uniform vec2 res;
uniform vec3 lightPos;
uniform float roughness;
uniform float metallic;

vec3 env(vec3 dir) {
	vec3 crd = vec3(0.5) + normalize(dir) * 0.5;
	vec3 sky = vec3(0.5, 0.7, 1.0);
	vec3 sky2 = vec3(0.6, 0.3, 0.0);
	vec3 water = vec3(0.1, 0.3, 0.4);
	vec3 color = mix(water, sky2,
		smoothstep(0.4, 0.5, crd.y));
	color = mix(color, sky,
		smoothstep(0.3, 0.9, crd.y));
	float th = 0.1;
	color.rgb += (smoothstep(0.0, th, abs(dir.y)) - 1.0) * 0.2;

	float l = pow(max(0.0, dot(dir, lightPos)), 24.0);
	color.rgb += vec3(1.0, 0.8, 0.6) * l;

	return clamp(color, vec3(0.0), vec3(1.0));
}

float SDF(vec3 p) {
    float radius = 0.25;
    return length(p)-radius;
}

vec3 getNormal(vec3 P) {	
	vec3 N;
	vec2 h = vec2(0.01, 0.0);
	N.x	= SDF(P + h.xyy) - SDF(P - h.xyy);
	N.y	= SDF(P + h.yxy) - SDF(P - h.yxy);
	N.z	= SDF(P + h.yyx) - SDF(P - h.yyx);
	return normalize(N);
}

float raymarch(vec3 eye, vec3 rayDir) {
    float dist = 0.0;
		float threshold = 0.005;
    for(int i = 0 ; i < 16 ; ++i) {
        float d = SDF(eye + rayDir * dist);
        if(d < threshold) { return dist; }
        dist += d;
    }
    return -1.0;
}

void main(void)
{
  vec2 crd = (gl_FragCoord.xy - res * 0.5) / min(res.x, res.y);

	vec3 eye = vec3(0.0, 0.0, -2.5);
	vec3 rayDir = normalize(vec3(crd, 0.0) - eye);
	float dist = raymarch(eye, rayDir);

	vec4 color = vec4(env(rayDir), 1.0);
	if (dist >= 0.0) {
			vec3 P = eye + rayDir * dist;
			vec3 N = getNormal(P);
			vec3 R = reflect(rayDir, N);
			color = mix(color, vec4(env(R), 1.0),
				smoothstep(0.0, 0.1, dot(-rayDir, N)));
	}
  gl_FragColor = color;
}`;

